<?php require_once __DIR__.'/includes/bootstrap.php';$publicTitle='Start Your CuePOS Trial | Snooker Club Software';$publicDescription='Create a private CuePOS workspace for your snooker club and begin a 14-day free trial.';$publicCanonical=siteUrl('/trial.php');$selectedPlan=$_GET['plan']??'starter';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrf();$owner=sanitize($_POST['owner_name']??'');$email=filter_var($_POST['email']??'',FILTER_VALIDATE_EMAIL);$password=$_POST['password']??'';$club=sanitize($_POST['club_name']??'');$country=strtoupper(substr(sanitize($_POST['country_code']??''),0,2));$timezone=sanitize($_POST['timezone']??'UTC');$currency=currencyForCountry($country);$planSlug=preg_replace('/[^a-z0-9_-]/','',strtolower($_POST['plan_slug']??'starter'));if(!$owner||!$email||!$club||strlen($password)<10){$error='Enter your name, club name, a valid email, and a password of at least 10 characters.';}elseif(!in_array($timezone,timezone_identifiers_list(),true)){$error='Choose a valid time zone.';}else{try{$db=getDB();$db->beginTransaction();$p=$db->prepare('SELECT * FROM plans WHERE slug=? AND is_public=1 LIMIT 1');$p->execute([$planSlug]);$plan=$p->fetch();if(!$plan)throw new RuntimeException('That plan is not available.');$exists=$db->prepare('SELECT id FROM users WHERE email=? LIMIT 1');$exists->execute([$email]);if($exists->fetchColumn())throw new RuntimeException('An account already exists with that email. Please log in instead.');$base=slugify($club);$slug=$base;$n=2;$check=$db->prepare('SELECT id FROM clubs WHERE slug=? LIMIT 1');while(true){$check->execute([$slug]);if(!$check->fetchColumn())break;$slug=$base.'-'.$n++;}$token=bin2hex(random_bytes(16));$q=$db->prepare("INSERT INTO clubs(name,slug,address,phone,tv_token,country_code,timezone,locale,currency_code,currency_symbol,tenant_status,trial_ends_at) VALUES(?,?,?,?,?,?,?,?,?,?, 'trial',DATE_ADD(NOW(),INTERVAL 14 DAY))");$q->execute([$club,$slug,null,null,$token,$country?:null,$timezone,'en',$currency[0],$currency[1]]);$clubId=(int)$db->lastInsertId();$q=$db->prepare("INSERT INTO users(club_id,name,email,password,role,is_active) VALUES(?,?,?,?, 'owner',1)");$q->execute([$clubId,$owner,$email,password_hash($password,PASSWORD_DEFAULT)]);$userId=(int)$db->lastInsertId();$db->prepare("INSERT INTO club_memberships(club_id,user_id,membership_role,status,joined_at) VALUES(?,?, 'owner','active',NOW())")->execute([$clubId,$userId]);$db->prepare("INSERT INTO subscriptions(club_id,plan_id,status,billing_interval,trial_ends_at,starts_at) VALUES(?,?, 'trial','monthly',DATE_ADD(NOW(),INTERVAL 14 DAY),NOW())")->execute([$clubId,$plan['id']]);$db->prepare("INSERT INTO trial_signups(club_id,owner_user_id,email,plan_id,source,created_at) VALUES(?,?,?,?, 'website',NOW())")->execute([$clubId,$userId,$email,$plan['id']]);$db->prepare("INSERT INTO rate_plans(club_id,plan_name,billing_type,rate_per_minute) VALUES(?, 'Standard Rate','per_minute',10)")->execute([$clubId]);$rateId=(int)$db->lastInsertId();$tableLimit=min(6,(int)$plan['table_limit']);$t=$db->prepare("INSERT INTO tables(club_id,table_number,table_name,table_type,status,rate_plan_id) VALUES(?,?,?,'snooker','available',?)");for($i=1;$i<=$tableLimit;$i++)$t->execute([$clubId,(string)$i,'Table '.$i,$rateId]);$settings=$db->prepare('INSERT INTO settings(club_id,setting_key,setting_value) VALUES(?,?,?)');foreach(['onboarding_complete'=>'0','subscription_plan'=>$plan['slug'],'trial_notice'=>'1'] as $k=>$v)$settings->execute([$clubId,$k,$v]);$db->commit();session_regenerate_id(true);$_SESSION=['user_id'=>$userId,'user_name'=>$owner,'user_role'=>'owner','club_id'=>$clubId,'club_name'=>$club,'currency_symbol'=>$currency[1],'currency_code'=>$currency[0],'csrf_token'=>bin2hex(random_bytes(32))];header('Location: '.url('dashboard.php?welcome=trial'));exit;}catch(Throwable $e){if(isset($db)&&$db->inTransaction())$db->rollBack();$error=$e->getMessage();}}}require __DIR__.'/includes/public-header.php';$plans=publicPlans(); ?><main class="max-w-5xl mx-auto px-5 py-20 grid lg:grid-cols-[1fr_.9fr] gap-12"><section><span class="eyebrow">14-day free trial</span><h1 class="font-display text-5xl font-extrabold mt-5">Create your private club workspace.</h1><p class="text-lg text-slate-600 leading-8 mt-5">Set up CuePOS for your snooker club in minutes. During the trial you can configure tables, prices, staff, players and café items before running the floor.</p><div class="mt-10 space-y-4"><?php foreach(['No credit card during the trial','A separate, secure workspace for your club','Tables and a starter rate plan created automatically','Configure your country, time zone and currency preferences'] as $benefit): ?><p class="flex gap-3"><i class="fa-solid fa-circle-check check mt-1"></i><span><?=$benefit?></span></p><?php endforeach; ?></div></section><form method="post" class="bg-white border border-slate-200 rounded-3xl p-7 shadow-sm"><input type="hidden" name="csrf_token" value="<?=csrfToken()?>"><?php if($error): ?><div class="mb-5 p-3 rounded-lg bg-red-50 border border-red-200 text-red-800 text-sm"><?=sanitize($error)?></div><?php endif; ?><h2 class="font-display text-2xl font-bold">Start your trial</h2><div class="space-y-4 mt-6"><label><span class="label text-slate-600">Your name</span><input class="input bg-white" required name="owner_name" value="<?=sanitize($_POST['owner_name']??'')?>"></label><label><span class="label text-slate-600">Club name</span><input class="input bg-white" required name="club_name" value="<?=sanitize($_POST['club_name']??'')?>"></label><label><span class="label text-slate-600">Business email</span><input class="input bg-white" required type="email" name="email" value="<?=sanitize($_POST['email']??'')?>"></label><label><span class="label text-slate-600">Password</span><input class="input bg-white" required type="password" minlength="10" name="password" placeholder="At least 10 characters"></label><div class="grid grid-cols-2 gap-3"><label><span class="label text-slate-600">Country code</span><input class="input bg-white" maxlength="2" name="country_code" placeholder="PK" value="<?=sanitize($_POST['country_code']??'')?>"></label><label><span class="label text-slate-600">Time zone</span><select class="input bg-white" name="timezone"><option value="UTC">UTC</option><?php foreach(['Asia/Karachi','Europe/London','America/New_York','Asia/Dubai','Australia/Sydney'] as $tz):?><option <?=($_POST['timezone']??'')===$tz?'selected':''?> value="<?=$tz?>"><?=$tz?></option><?php endforeach?></select></label></div><label><span class="label text-slate-600">Plan after trial</span><select class="input bg-white" name="plan_slug"><?php foreach($plans as $p):?><option <?=($selectedPlan===$p['slug']?'selected':'')?> value="<?=sanitize($p['slug'])?>"><?=sanitize($p['name'])?><?= $p['price_monthly']?' — $'.number_format($p['price_monthly'],0).'/month':''?></option><?php endforeach?></select></label></div><button class="w-full mt-7 rounded-full bg-ink text-white py-3.5 font-bold">Create my CuePOS workspace <i class="fa-solid fa-arrow-right ml-1"></i></button><p class="text-xs text-slate-500 leading-5 mt-4">By creating a workspace, you agree to the CuePOS terms and privacy policy. No payment is collected during the trial.</p></form></main><?php require __DIR__.'/includes/public-footer.php'; ?>
